package com.hbm.entity.mob.maskman;
import com.hbm.explosion.vanillant.ExplosionVNT;import com.hbm.explosion.vanillant.interfaces.*;import com.hbm.explosion.LegacyExplosionMath;import net.minecraft.core.BlockPos;import net.minecraft.world.level.Level;import java.util.HashSet;
/** Original BlockProcessorNoDamage, including real fire mutation and suppressing block debris. */
public final class MaskManNoBlockDamage implements IBlockProcessor {private IBlockMutator convert;public MaskManNoBlockDamage withBlockEffect(IBlockMutator value){convert=value;return this;}@Override public void process(ExplosionVNT explosion,Level world,double x,double y,double z,HashSet<BlockPos> affected){for(var pos:affected){var state=world.getBlockState(pos);if(!state.isAir()&&convert!=null)convert.mutatePre(explosion,state,LegacyExplosionMath.metadata(state),pos.getX(),pos.getY(),pos.getZ());}if(convert!=null)for(var pos:affected)if(world.getBlockState(pos).isAir())convert.mutatePost(explosion,pos.getX(),pos.getY(),pos.getZ());affected.clear();}}
